import{_ as i,l,o as e,c as n,v as t,p as s,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"页面置换的竞争分析","description":"","frontmatter":{"title":"页面置换的竞争分析","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/paging-competitive.md","filePath":"cs/paging-competitive.md","lastUpdated":1789023840000}'),h={name:"cs/paging-competitive.md"};function _(m,a,k,u,B,T){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="页面置换的竞争分析" tabindex="-1">页面置换的竞争分析 <a class="header-anchor" href="#页面置换的竞争分析" aria-label="Permalink to &quot;页面置换的竞争分析&quot;">​</a></h1><div class="epigraph"><p>$k$ 槽缓存，缺页代价 1；FIFO/LRU 对确定性对手 $k$-竞争，最优离线是 Belady 最远未来。</p><footer>—— 据 Sleator and Tarjan, 1985；Belady, A Study of Replacement Algorithms, 1966；CLRS 第 15 章对照整理</footer></div><p>上一课<a href="/cs/competitive-ratio">在线算法与竞争比</a>给了 \\(\\rho\\)。操作系统缓存：页面置换。缺口是 LRU/FIFO 的 \\(k\\)-竞争，以及确定性下界 \\(k\\)。不重写竞争比定义。后课租买是更简单的 2-竞争原型。不写具体内核 LRU 实现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>请求序列 \\(p_1,p_2,\\ldots\\)，槽 \\(k\\)。缺页则换出。离线 MIN：换出最远才再用的（Belady）。LRU：换出最久未用。Sleator–Tarjan：LRU 是 \\(k\\)-竞争；任何确定性算法 \\(\\ge k\\)。随机标记算法对 oblivious 约 \\(H_k\\)-竞争。</p><p>缺口是缓存，不是列表更新（虽同一篇论文）。</p><h3 id="不是工作集调参" tabindex="-1">不是工作集调参 <a class="header-anchor" href="#不是工作集调参" aria-label="Permalink to &quot;不是工作集调参&quot;">​</a></h3><p>竞争比不依赖输入分布。工作集是实践启发式。不要把调参数当 \\(\\rho\\) 证明。</p><p><span class="marginnote">Belady 1966 离线最优。Sleator–Tarjan 在线。后课 ski-rental 更干净的 2-竞争。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>势：在线缓存与 OPT 缓存的差集大小一类。缺页时势变证明摊还 \\(\\le k\\cdot\\) OPT 缺页。下界：交错 \\(k+1\\) 页。</p>',11)),(e(),s(c,null,{default:r(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E9%A1%B5%E9%9D%A2%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20LRU%5B%22LRU%20%2F%20FIFO%22%5D%0A%20%20LRU%20--%3E%20K%5B%22k-%E7%AB%9E%E4%BA%89%22%5D%0A%20%20OFF%5B%22Belady%20MIN%22%5D%20--%3E%20OPT%5B%22%E7%A6%BB%E7%BA%BF%E6%9C%80%E4%BC%98%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>写回代价可折进模型，本课单位缺页。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>OPT 每缺一次可以「覆盖」在线 \\(k\\) 次缺的势债。对手总请求不在在线槽内的那页。与 \\(k\\)-server 在度量空间是推广。与 OS 课 LRU 近似硬件：本课纯竞争。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 ARC 等自适应。不写多层缓存。后课默认：分页 LRU \\(k\\)-竞争。下一课租买问题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LRU/FIFO 确定性 \\(k\\)-竞争，下界 \\(k\\)。</li><li>离线 Belady 最远未来。</li><li>随机对 oblivious 可到 \\(H_k\\)。</li><li>出处：Sleator and Tarjan, 1985；Belady, 1966。</li></ul>',7))])}const E=i(h,[["render",_]]);export{A as __pageData,E as default};
